// js/madrid-tiles.js — phase-3 tile streaming policy: which geodata tiles stay resident around the camera, in what
// order they are fetched, and which ones are evicted when the memory budget is exceeded.
//
// The manifest (tools/madrid/tiles.json, generated by tools/madrid/tiles.mjs) lists every 1 km cell of the almendra
// central with its core rectangles (world metres), its fetch box, status and the md5/size of its module. Only tiles
// with status "ready" are streamed; the seed tile (phase 2, js/madrid-geodata.js) is already part of the world.
//
// Budget: 12 MB of geodata modules resident (the size recorded in the manifest, i.e. what the browser downloaded),
// at most 12 tiles, prefetch within 1 600 m of the camera's ground position and evict beyond 2 600 m.
import { importTileModule } from './madrid-tile-import.js';

export const tileBytes = (tile) => (tile.bytes || 0) + (tile.blocksBytes || 0);

export const TILE_BUDGET = Object.freeze({
  maxResidentBytes: 12 * 1024 * 1024,
  maxResidentTiles: 12,
  preloadRadius: 1600,
  dropRadius: 2600
});
export const SEED_TILE_ID = 'fase2';

/** Distance (m) from a world point to the nearest core rectangle of a tile. */
export function distanceToCore(tile, x, z) {
  let best = Infinity;
  const core = tile.core && tile.core.length ? tile.core : [tile.frame?.bbox];
  for (const r of core) {
    if (!r) continue;
    const dx = Math.max(r[0] - x, 0, x - r[2]);
    const dz = Math.max(r[1] - z, 0, z - r[3]);
    const d = Math.hypot(dx, dz);
    if (d < best) best = d;
  }
  return best;
}

/**
 * Pure streaming decision for one camera position.
 * @param {object} o
 * @param {Array<{id:string,status:string,core:number[][],bytes:number}>} o.tiles  every tile of the manifest
 * @param {Map<string,{bytes:number}>|Set<string>} o.loaded  tiles currently in the world
 * @param {number} o.x world x (east) of the camera's ground position
 * @param {number} o.z world z (south)
 * @param {number} o.bytes resident bytes right now
 * @param {object} [o.budget] TILE_BUDGET fields, any subset
 * @returns {{load: string[], drop: string[], distances: Map<string, number>}}
 */
export function planTiles({ tiles, loaded, x, z, bytes = 0, budget = TILE_BUDGET, vx = 0, vz = 0 }) {
  const b = { ...TILE_BUDGET, ...budget };
  const has = (id) => loaded.has(id);
  const sizeOf = (t) => loaded.get?.(t.id)?.bytes ?? tileBytes(t);
  // Speed-aware look-ahead (tinywarsaw engine notes): while the camera moves, prefetch what the velocity vector
  // reaches in LOOKAHEAD_S instead of what surrounds the current position, so a flight never frames an unbuilt
  // tile ahead. Eviction still uses the true position: what you leave behind is dropped as before.
  const LOOKAHEAD_S = 6;
  const speed = Math.hypot(vx, vz);
  const ahead = Math.min(speed * LOOKAHEAD_S, b.preloadRadius * 1.5); // clamp: a fast jet must not pull half the map
  const ax = speed > 0.1 ? x + (vx / speed) * ahead : x;
  const az = speed > 0.1 ? z + (vz / speed) * ahead : z;
  const distances = new Map();
  for (const t of tiles) distances.set(t.id, distanceToCore(t, x, z));
  const aheadDistances = new Map();
  for (const t of tiles) aheadDistances.set(t.id, distanceToCore(t, ax, az));

  const drop = [];
  const dropped = new Set();
  let resident = bytes;
  let count = tiles.filter((t) => has(t.id)).length;
  const evict = (t) => {
    if (t.id === SEED_TILE_ID) return; // the seed is the world the app boots into: never evicted
    drop.push(t.id);
    dropped.add(t.id);
    resident -= sizeOf(t);
    count--;
  };
  const byDistanceDesc = (list) => list.sort((p, q) => (distances.get(q.id) ?? Infinity) - (distances.get(p.id) ?? Infinity));

  // 1. Out of range: release everything beyond the drop radius, farthest first.
  for (const t of byDistanceDesc(tiles.filter((t) => has(t.id) && !dropped.has(t.id)))) {
    if ((distances.get(t.id) ?? Infinity) > b.dropRadius) evict(t);
  }
  // 2. Hard caps: the resident set may never exceed the byte or tile budget, even with no camera movement.
  for (const t of byDistanceDesc(tiles.filter((t) => has(t.id) && !dropped.has(t.id)))) {
    if (resident <= b.maxResidentBytes && count <= b.maxResidentTiles) break;
    evict(t);
  }
  // 3. Prefetch the nearest ready tiles that fit (nearest first; no eviction beyond the caps above).
  const load = [];
  const candidates = tiles
    .filter((t) => t.status === 'ready' && !has(t.id) && !dropped.has(t.id) && (aheadDistances.get(t.id) ?? Infinity) <= b.preloadRadius)
    .sort((p, q) => (aheadDistances.get(p.id) ?? Infinity) - (aheadDistances.get(q.id) ?? Infinity));
  for (const t of candidates) {
    const fits = () => resident + sizeOf(t) <= b.maxResidentBytes && count + 1 <= b.maxResidentTiles;
    if (!fits()) {
      // A full set must not strand the player outside an unloaded nearby core. Trade farther residents for nearer
      // candidates, with hysteresis so standing on a seam does not churn the same tiles every update.
      const farther = byDistanceDesc(tiles.filter((p) => has(p.id) && p.id !== SEED_TILE_ID && !dropped.has(p.id) &&
        distances.get(p.id) > distances.get(t.id) + 200));
      for (const p of farther) { evict(p); if (fits()) break; }
    }
    if (!fits()) continue;
    load.push(t.id);
    resident += sizeOf(t);
    count++;
  }
  return { load, drop, distances };
}

/**
 * Runtime streamer: fetches the manifest, imports tile modules on demand and hands them to the tile world.
 * `importModule` is injectable so the policy can be exercised without a browser.
 */
export async function createTileStreamer({
  world,
  manifestUrl = './tools/madrid/tiles.json',
  baseUrl = globalThis.document?.baseURI ?? './',
  budget = {},
  seedBytes = 0,
  importModule = importTileModule,
  fetchJson = async (url) => {
    const res = await fetch(url, { cache: 'no-cache' });
    if (!res.ok) throw new Error(`tiles manifest ${res.status}`);
    return res.json();
  },
  onStatus = null,
  onTileAdded = null,
  onTileRemoved = null
} = {}) {
  const manifest = await fetchJson(new URL(manifestUrl, baseUrl).href);
  const budgetCfg = { ...TILE_BUDGET, ...manifest.budget, ...(budget || {}) };
  const tiles = (manifest.tiles || []).filter((t) => t.status === 'ready');
  const loaded = new Map();
  const seed = tiles.find((t) => t.id === SEED_TILE_ID);
  if (seed) loaded.set(SEED_TILE_ID, { bytes: seedBytes || tileBytes(seed) });
  if ((loaded.get(SEED_TILE_ID)?.bytes || 0) > budgetCfg.maxResidentBytes) throw new Error('Tile budget cannot hold the seed');
  const retries = new Map();
  const inFlight = new Map();
  let disposed = false;
  let lastX = Infinity, lastZ = Infinity, lastAt = -Infinity;
  let failures = 0;

  const status = () => ({
    loaded: [...loaded.keys()],
    bytes: [...loaded.values()].reduce((n, v) => n + v.bytes, 0),
    reservedBytes: [...inFlight.values()].reduce((n, v) => n + v.bytes, 0),
    inFlight: [...inFlight.keys()],
    failures,
    available: tiles.length
  });

  async function loadTile(id) {
    const tile = tiles.find((t) => t.id === id);
    // One retry, then the tile is left alone (no request storms); at most three modules in flight at once.
    if (disposed || !tile || loaded.has(id) || inFlight.has(id) || (retries.get(id) || 0) >= 2 || inFlight.size >= 3) return false;
    const bytes = tileBytes(tile);
    const current = status();
    if (current.bytes + current.reservedBytes + bytes > budgetCfg.maxResidentBytes ||
        loaded.size + inFlight.size >= budgetCfg.maxResidentTiles) return false;
    const controller = new AbortController();
    const reservation = { bytes, controller };
    inFlight.set(id, reservation);
    const t0 = performance.now();
    try {
      // The module URL carries the manifest hash: a deployed tile is fetched once and can never be served stale.
      const url = new URL(`${tile.module}?v=${tile.md5 || '0'}`, baseUrl).href;
      const mod = await importModule(url, { signal: controller.signal });
      const data = mod.TILE;
      if (!data || data.id !== id) throw new Error(`module ${tile.module} does not export TILE ${id}`);
      if (disposed || controller.signal.aborted) return false;
      // A budget can change while a request is in flight. Recheck before allocating any scene objects.
      if (status().bytes + bytes > budgetCfg.maxResidentBytes || loaded.size >= budgetCfg.maxResidentTiles) return false;
      world.addTile({ ...data, bytes });
      loaded.set(id, { bytes, objects: world.meshCount() });
      inFlight.delete(id);
      onTileAdded?.(data);
      console.info(`[madrid-tiles] +${id} ${Math.round(performance.now() - t0)}ms ${tile.bytes} B (${status().loaded.length} resident)`);
      onStatus?.(status());
      return true;
    } catch (err) {
      if (err.name === 'AbortError' || controller.signal.aborted) return false;
      const n = (retries.get(id) || 0) + 1;
      retries.set(id, n);
      if (n === 1) console.warn(`[madrid-tiles] ${id} failed, will retry once: ${err.message}`);
      else {
        failures++;
        console.warn(`[madrid-tiles] ${id} unavailable: ${err.message}`);
      }
      onStatus?.(status());
      return false;
    } finally {
      if (inFlight.get(id) === reservation) inFlight.delete(id);
    }
  }

  function dropTile(id) {
    if (id === SEED_TILE_ID) return;
    inFlight.get(id)?.controller.abort();
    inFlight.delete(id);
    if (world.removeTile(id)) {
      loaded.delete(id);
      retries.delete(id);
      onTileRemoved?.(id);
      console.info(`[madrid-tiles] -${id} (${status().loaded.length} resident, ${status().bytes} B)`);
      onStatus?.(status());
    }
  }

  /** Call every frame (cheap) or a few times per second; it self-throttles to 20 m / 400 ms. */
  function update(x, z, now = performance.now()) {
    if (disposed) return null;
    const moved = Math.hypot(x - lastX, z - lastZ);
    if (moved < 20 && now - lastAt < 400) return null;
    const dt = Number.isFinite(lastAt) ? (now - lastAt) / 1000 : 0;
    const vx = dt > 0 ? (x - lastX) / dt : 0;
    const vz = dt > 0 ? (z - lastZ) / dt : 0;
    lastX = x; lastZ = z; lastAt = now;
    for (const id of inFlight.keys()) {
      if (distanceToCore(tiles.find((t) => t.id === id), x, z) > budgetCfg.dropRadius) dropTile(id);
    }
    const plan = planTiles({
      tiles: tiles.filter((t) => loaded.has(t.id) || (retries.get(t.id) || 0) < 2),
      loaded,
      x,
      z,
      vx,
      vz,
      bytes: [...loaded.values()].reduce((n, v) => n + v.bytes, 0),
      budget: budgetCfg
    });
    for (const id of plan.drop) dropTile(id);
    for (const id of plan.load) loadTile(id);
    return plan;
  }

  return {
    manifest, tiles, update, loadTile, dropTile, status, loaded, budget: budgetCfg,
    dispose() {
      disposed = true;
      for (const id of [...inFlight.keys(), ...loaded.keys()]) dropTile(id);
    }
  };
}

/**
 * Madrid facade palettes for the tile world (phase-4 style). The seed table FACADE_DEFS in buildings.js is
 * Manhattan pre-war masonry; these are the almendra anchors instead (references in MADRID.md): caliza blanca de
 * Colmenar, ladrillo visto and revoco encalado, with Madrid residential rhythm - narrow bays for balcones de
 * forja (~1.5 m) and ~3.1-3.4 m floors - instead of the 2.2-2.6 m New York bays and storefront fronts.
 * Plain data so the choice stays testable in Node; madrid-tile-world.js pairs each entry with FACADE_DEFS' factory.
 */
export const MADRID_FACADE_OPTS = Object.freeze([
  Object.freeze({ // 0: caliza blanca (Gran Via / Palacio Real limestone)
    stoneColor: 0xe7ddc6,
    trimColor: 0xcfc2a6,
    windowGlassColor: 0x202e3a,
    windowWidth: 1.5,
    floorHeight: 3.4,
    litProbability: 0.5,
    warmth: 0.85,
    seed: 21.7
  }),
  Object.freeze({ // 1: ladrillo visto rojizo (residencial / neomudejar)
    stoneColor: 0xa45538,
    trimColor: 0xd8c39a,
    windowGlassColor: 0x1c2833,
    windowWidth: 1.5,
    floorHeight: 3.3,
    litProbability: 0.48,
    warmth: 0.9,
    seed: 33.2
  }),
  Object.freeze({ // 2: revoco ocre claro (La Latina / Lavapies - el ocre luminoso de Tiny-Madrid)
    stoneColor: 0xe0ba7f,
    trimColor: 0xf0e2c2,
    windowGlassColor: 0x243441,
    windowWidth: 1.4,
    floorHeight: 3.1,
    litProbability: 0.45,
    warmth: 0.95,
    seed: 47.9
  }),
  Object.freeze({ // 3: revoco salmon rosado (acentos del casco antiguo en Tiny-Madrid)
    stoneColor: 0xdc9d7e,
    trimColor: 0xecd3b8,
    windowGlassColor: 0x223038,
    windowWidth: 1.4,
    floorHeight: 3.2,
    litProbability: 0.45,
    warmth: 0.95,
    seed: 58.3
  })
]);

/** Face treatment for tile parcels: residential fronts with entrance bays, not four NYC storefronts. */
export const MADRID_PARCEL_FACE = 'entry';

/**
 * Named-monument facade styles for the tile world: each identified landmark gets the material of its real
 * reference (caliza blanca de Colmenar, granito berroqueno, the red fronts of the Plaza Mayor), not one blanket
 * tone. First regex that matches the OSM name wins; unmatched landmarks keep the neutral stone default.
 */
export const MADRID_LANDMARK_STYLES = Object.freeze([
  Object.freeze([/\bpalacio real\b/i, Object.freeze({ color: 0xece5d3, roughness: 0.7 })]),
  Object.freeze([/\balmudena\b/i, Object.freeze({ color: 0xe8e1cf, roughness: 0.72 })]),
  Object.freeze([/\bplaza de toros\b/i, Object.freeze({ color: 0x9a4b38, roughness: 0.8 })]),
  Object.freeze([/\bpuerta de alcal/i, Object.freeze({ color: 0xe5dfce, roughness: 0.65 })]),
  Object.freeze([/\bcibeles\b/i, Object.freeze({ color: 0xeae3d1, roughness: 0.7 })]),
  Object.freeze([/\bmetr[oó]polis\b/i, Object.freeze({ color: 0xdfd7c2, roughness: 0.68 })]),
  Object.freeze([/\bteatro real\b/i, Object.freeze({ color: 0xe6dfd0, roughness: 0.7 })]),
  Object.freeze([/\bplaza mayor\b/i, Object.freeze({ color: 0xb0624a, roughness: 0.8 })]),
  Object.freeze([/\bcasa de la panader[ií]a\b/i, Object.freeze({ color: 0xa8574a, roughness: 0.78 })]),
  Object.freeze([/\btemplo de debod\b/i, Object.freeze({ color: 0xc9b18a, roughness: 0.8 })]),
  Object.freeze([/\bbanco de espa[nñ]a\b/i, Object.freeze({ color: 0xe6dfcd, roughness: 0.7 })]),
  Object.freeze([/\b(catedral|iglesia|basilica|basílica|ermita)\b/i, Object.freeze({ color: 0xe3dcc8, roughness: 0.74 })])
]);
